namespace InterceptorSetup {
 public static class App {
  public static bool Administrator {get{return new WindowsPrincipal(WindowsIdentity.GetCurrent()).IsInRole(WindowsBuiltInRole.Administrator);}}
  [STAThread] public static int Main(string[] args) {
   try {
    if(args.Length>=1&&args[0]=="--self-test") {
     string verified=Package.Verify();string signingMode=Package.SigningMode();Package.ValidateName("Payload/Interceptor.sys");int rejected=0;foreach(string path in new[]{"../oops","a/../../oops","/oops","C:/oops","a\\oops"})try{Package.ValidateName(path);}catch(InvalidDataException){rejected++;}
     DiagnosticWindow.SelfTest();if(rejected!=5)throw new Exception("Path traversal regression.");if(Marshal.SizeOf(typeof(IcStatus))!=64 || Marshal.SizeOf(typeof(IcCapabilities))!=64)throw new Exception("ABI layout regression.");
     if(Native.KindOf("HIDClass","","HID_DEVICE_SYSTEM_GAME","")!="HID controller" || Native.KindOf("HIDClass","","","HID_DEVICE_UP:0001_U:0005")!="HID controller" || Native.KindOf("HIDClass","","HID_DEVICE_UP:0001_U:0006","")!="")throw new Exception("Controller inventory classification regression.");LoadWindow();
     if(Native.KindOf("HIDClass","hidusb","","HID_DEVICE_UP:0001_U:0005","other;xinputhid")!="XInputHID" || Native.KindOf("XboxComposite","dc1-controller","",@"USB\MS_COMP_XGIP10")!="GIP" || Native.KindOf("System","Interceptor",@"ROOT\InterceptorControl","")!="Control" || Native.KindOf("HIDClass","","","HID_DEVICE_UP:0001_U:00050")!="")throw new Exception("Native controller inventory regression.");
     var cap=new IcCapabilities{Size=64,Version=1,Abi=4,Inputs=3,Controllers=15,MaxDevices=256,QueueCapacity=8192,MaxSend=256,HidReportMax=1024};
     if(!Native.ValidCapabilities(cap,64)||Native.ValidCapabilities(cap,63))throw new Exception("Capability validation regression.");cap.Inputs=0;if(Native.ValidCapabilities(cap,64))throw new Exception("Combined product must advertise keyboard and mouse.");cap.Inputs=3;cap.Reserved1=1;if(Native.ValidCapabilities(cap,64))throw new Exception("Reserved capabilities regression.");
     WriteResult(args.Length>1?args[1]:"InterceptorSetup-self-test.json",new{passed=true,package=verified,driverSigningMode=signingMode,maliciousPathsRejected=rejected,controllerInventoryCases=7,capabilityCases=4,abiBytes=64,xaml="parsed",installedAnything=false});return 0;
    }
    if(args.Length==2&&args[0]=="--snapshot"){WriteResult(args[1],Native.Inspect());return 0;}
    if(args.Length==2&&args[0]=="--benchmark"){WriteResult(args[1],new{result=Native.Benchmark(),measurement="STATUS IOCTL round trip; not hardware input latency"});return 0;}
    if(args.Length==3&&args[0]=="--action") {string action=args[1];if(action!="Install"&&action!="Uninstall"&&action!="Associate"&&action!="CompleteAssociation")throw new ArgumentException("Actions: Install, Uninstall, Associate, CompleteAssociation.");var log=new List<string>();object gate=new object();int result=Package.Execute(action,x=>{lock(gate)log.Add(x);},x=>{lock(gate)log.Add(x);});WriteResult(args[2],new{action=action,exitCode=result,rebootRequired=result==3010,log=log.ToArray()});return result;}
    if(args.Length==2&&args[0]=="--diagnostic-preview"){var previewApp=new Application();var preview=new DiagnosticWindow(null,true,args[1]);previewApp.Run(preview.Window);return 0;}
    bool screenshot=args.Length==2&&args[0]=="--smoke-ui";
    if(args.Length!=0&&!screenshot)throw new ArgumentException("Arguments: --self-test [JSON], --snapshot JSON, --benchmark JSON, --smoke-ui PNG, --action Install|Uninstall|Associate JSON.");
    if(!screenshot&&!Administrator){try{Process.Start(new ProcessStartInfo(Assembly.GetExecutingAssembly().Location){UseShellExecute=true,Verb="runas",WorkingDirectory=Environment.CurrentDirectory});return 0;}catch(Win32Exception e){if(e.NativeErrorCode==1223)return 1223;throw;}}
    var app=new Application();var window=LoadWindow();var controller=new Dashboard(window,screenshot?args[1]:null);app.Run(window);GC.KeepAlive(controller);return 0;
   }catch(Exception e){try{string path=Path.Combine(Path.GetTempPath(),"InterceptorSetup-error-"+Process.GetCurrentProcess().Id+".txt");File.WriteAllText(path,e.ToString(),Encoding.UTF8);if(args.Length>=2&&new[]{"--self-test","--snapshot","--benchmark","--action"}.Contains(args[0]))WriteResult(args[args.Length-1],new{passed=false,error=e.Message,detail=e.ToString(),diagnostic=path});if(args.Length==0)MessageBox.Show(e.Message+"\n\nDiagnostics: "+path,"Interceptor",MessageBoxButton.OK,MessageBoxImage.Error);}catch{}return 1;}
  }
  static Window LoadWindow(){using(var reader=XmlReader.Create(new StringReader(Package.TextResource("MainWindow.xaml")),new XmlReaderSettings{DtdProcessing=DtdProcessing.Prohibit,XmlResolver=null}))return (Window)XamlReader.Load(reader);}
  public static void WriteResult(string path,object value){File.WriteAllText(Path.GetFullPath(path),Package.Json.Serialize(value),Encoding.UTF8);}
 }
 public sealed class Dashboard {
  readonly Window window;readonly string screenshot;readonly List<string> logs=new List<string>();readonly object logLock=new object();readonly DispatcherTimer debounce=new DispatcherTimer();readonly DispatcherTimer inputTimer=new DispatcherTimer();
  Snapshot snapshot;bool busy,refreshing,refreshAgain,closed,testing;IntPtr hwnd,rawBuffer;readonly Dictionary<IntPtr,string> rawNames=new Dictionary<IntPtr,string>();HwndSource source;long inputCount,lastInputTick;double maxGap;string lastInput="",inputTarget="";readonly Stopwatch inputClock=new Stopwatch();string benchmark="Not run";
  T Find<T>(string name)where T:FrameworkElement{return (T)window.FindName(name);}void Set(string name,string text){Find<TextBlock>(name).Text=text;}
  public Dashboard(Window window,string screenshot){this.window=window;this.screenshot=screenshot;
   bool microsoft=Package.SigningMode()=="Microsoft";
   Set("PackageEdition",(microsoft?"MICROSOFT-SIGNED DRIVER · ":"DEVELOPMENT · SIGNATURE PENDING · ")+Package.DriverVersion());
   Set("Hint",microsoft?"Startup recovery: interceptor.txt at the root of a USB drive or external disk · 30-second monitoring window.":"Development package: installation is disabled until this product receives its own Microsoft signature. No Windows setting will be changed.");
   Find<Button>("InstallButton").Click+=async(s,e)=>await Operation("Install");Find<Button>("UninstallButton").Click+=async(s,e)=>await Operation("Uninstall");Find<Button>("AssociateButton").Click+=async(s,e)=>await Operation("Associate");Find<Button>("RefreshButton").Click+=async(s,e)=>await Refresh();Find<Button>("ExportButton").Click+=(s,e)=>Export();Find<Button>("BenchmarkButton").Click+=async(s,e)=>await Benchmark();Find<Button>("InputButton").Click+=(s,e)=>StartInput();Find<Button>("RebootButton").Click+=(s,e)=>Reboot();
   Find<Button>("DiagnosticButton").Click+=async(s,e)=>await Diagnose();
   Find<DataGrid>("Devices").SelectionChanged+=(s,e)=>{var row=Find<DataGrid>("Devices").SelectedItem as DeviceRow;if(row!=null){Set("DeviceDetail",row.Explanation+"\n"+row.Instance+"\n"+row.ProfileSupport+" · Windows: "+row.WindowsState+" · INF: "+row.InstalledInf+" · Service: "+row.ServiceDisplay+(string.IsNullOrEmpty(row.Service)?" (a HID collection may use its parent stack)":"")+" · Filters: "+(row.Filters.Length==0?"none":row.Filters));if(!testing)Set("InputState","Test the selected row: "+row.Name);}};
   debounce.Interval=TimeSpan.FromMilliseconds(700);debounce.Tick+=async(s,e)=>{debounce.Stop();if(!busy)await Refresh();else refreshAgain=true;};inputTimer.Interval=TimeSpan.FromMilliseconds(100);inputTimer.Tick+=(s,e)=>InputTick();
   window.SourceInitialized+=(s,e)=>{hwnd=new WindowInteropHelper(window).Handle;source=HwndSource.FromHwnd(hwnd);source.AddHook(WndProc);};
   window.Closing+=(s,e)=>{if(busy){e.Cancel=true;Set("Hint","Wait for the operation to finish before closing this window. Progress appears in the log.");return;}StopInput();};
   window.Closed+=(s,e)=>{closed=true;debounce.Stop();inputTimer.Stop();if(source!=null)source.RemoveHook(WndProc);};
   window.Loaded+=async(s,e)=>{window.BeginAnimation(UIElement.OpacityProperty,new DoubleAnimation(0,1,TimeSpan.FromMilliseconds(200)));Log("Starting · "+(App.Administrator?"administrator":"read-only, not elevated"));if(screenshot==null&&App.Administrator){try{if(Package.PendingControllerAssociation()){Log("Resuming controller association requested by the previous installation.");await Operation("CompleteAssociation");}}catch(Exception error){Log("Cannot resume associations: "+error.Message);Set("Hint","Use Associate new devices to finish installation. "+error.Message);}}await Refresh();if(screenshot!=null){await Task.Delay(350);window.UpdateLayout();var bitmap=new RenderTargetBitmap((int)window.ActualWidth,(int)window.ActualHeight,96,96,PixelFormats.Pbgra32);bitmap.Render(window);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using(var file=File.Create(Path.GetFullPath(screenshot)))encoder.Save(file);window.Close();}};
  }
  void Ui(Action action){if(!closed)window.Dispatcher.BeginInvoke(action);}
  void Log(string value){string line=DateTime.Now.ToString("HH:mm:ss")+"  "+value;lock(logLock){logs.Add(line);if(logs.Count>5000)logs.RemoveRange(0,1000);}Ui(()=>{var box=Find<TextBox>("Log");if(box.Text.Length>100000)box.Text=box.Text.Substring(box.Text.Length-70000);box.AppendText(line+Environment.NewLine);box.ScrollToEnd();});}
  void Busy(bool value,string phase){busy=value;Find<ProgressBar>("Progress").Visibility=value?Visibility.Visible:Visibility.Collapsed;Set("Phase",phase);foreach(string name in new[]{"InstallButton","UninstallButton","AssociateButton","RefreshButton","BenchmarkButton","InputButton","DiagnosticButton"})Find<Button>(name).IsEnabled=!value;}
  async Task Diagnose(){if(busy)return;StopInput();Busy(true,"Diagnostics are running in a separate window…");try{var diagnostic=new DiagnosticWindow(window);diagnostic.Window.ShowDialog();Log("Diagnostic : "+diagnostic.Report.Errors+" error(s), "+diagnostic.Report.Unverified+" unverified check(s).");}finally{Busy(false,"Diagnostics closed · inventory refreshed.");}await Refresh();}
  async Task Refresh(){if(refreshing){refreshAgain=true;return;}refreshing=true;try{var result=await Task.Run(()=>Native.Inspect());if(closed)return;snapshot=result;Set("DriverState",result.DriverState);Set("DriverDetail",result.DriverPath);Set("ApiState",result.ApiState);Set("ApiDetail",result.ApiDetail);Set("DeviceCount",result.Devices.Count.ToString());Set("DeviceSummary",result.Devices.Count(x=>x.InterfaceActive)+" published interface(s) · "+result.Devices.Count(x=>x.Association.StartsWith("Associated"))+" association(s) to verify");Set("EnvironmentState",result.TestMode+"\n"+result.PackageState+"\n"+result.TrialState+"\nQueue overflows: "+result.Overflows);string selected=(Find<DataGrid>("Devices").SelectedItem as DeviceRow ?? new DeviceRow()).Instance;Find<DataGrid>("Devices").ItemsSource=result.Devices;Find<DataGrid>("Devices").SelectedItem=result.Devices.FirstOrDefault(x=>x.Instance==selected);Log("Inventory: "+result.Devices.Count+" device(s) · API "+result.ApiState);}
   catch(Exception e){Log("Inventory failed: "+e.Message);Set("Hint",e.Message);}finally{refreshing=false;if(refreshAgain&&!busy&&!closed){refreshAgain=false;debounce.Start();}}}
  async Task Operation(string action){if(busy)return;StopInput();Busy(true,"Preparing…");Set("Hint","This operation may restart devices. Details appear in the log.");try{int code=await Task.Run(()=>Package.Execute(action,Log,p=>Ui(()=>Set("Phase",p))));string phase=code==0?"Operation completed.":code==3010?"Operation completed · restart required.":"Operation failed · code "+code;Busy(false,phase);Find<Button>("RebootButton").Visibility=code==3010?Visibility.Visible:Visibility.Collapsed;Set("Hint",code==3010?(action=="Uninstall"?"Restart Windows to finish uninstalling.":"Restart Windows and reopen this installer to finish device association automatically."):code==0?"The status below is read directly from Windows.":"Review the log and export diagnostics. Installation scripts attempt recovery if installation fails.");Log(phase);}
   catch(Exception e){Busy(false,"Operation interrupted.");Set("Hint",e.Message);Log(e.ToString());}await Refresh();}
  async Task Benchmark(){if(busy)return;Find<Button>("BenchmarkButton").IsEnabled=false;Set("Latency","Measuring…");try{string value=await Task.Run(()=>Native.Benchmark());benchmark=value;int split=value.IndexOf('|');Set("Latency",value.Substring(0,split)+" µs");Set("LatencyDetail",value.Substring(split+1)+"\nSTATUS round trip, excluding hardware latency.");Log("API measurement: "+value.Replace('|',' ').Replace('\n',' '));}catch(Exception e){Set("Latency","Unavailable");Set("LatencyDetail",e.Message);Log("API measurement: "+e.Message);}finally{Find<Button>("BenchmarkButton").IsEnabled=!busy;}}
  void Export(){var dialog=new Microsoft.Win32.SaveFileDialog{FileName="Interceptor-diagnostic-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".json",Filter="Diagnostic JSON (*.json)|*.json"};if(dialog.ShowDialog(window)!=true)return;try{string[] copy;lock(logLock)copy=logs.ToArray();App.WriteResult(dialog.FileName,new{snapshot=snapshot,benchmark=benchmark,inputEvents=inputCount,inputLast=lastInput,largestObservedGapMs=maxGap,inputObservation="Windows Raw Input; no exclusive interception; event gaps depend on user activity",packageHashes=Package.Manifest(),log=copy});Log("Diagnostics exported: "+dialog.FileName);}catch(Exception e){Log("Export failed: "+e.Message);}}
  void Reboot(){if(MessageBox.Show(window,"Save your work before continuing. Restart Windows now?","Interceptor",MessageBoxButton.YesNo,MessageBoxImage.Question)!=MessageBoxResult.Yes)return;try{Process.Start(new ProcessStartInfo(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.System),"shutdown.exe"),"/r /t 0"){UseShellExecute=false,CreateNoWindow=true});}catch(Exception e){Log("Cannot restart: "+e.Message);}}
  void StartInput(){if(testing||busy)return;inputCount=0;lastInputTick=0;maxGap=0;lastInput="Waiting for Windows input…";var selected=Find<DataGrid>("Devices").SelectedItem as DeviceRow;inputTarget=selected==null?"":selected.Instance;var registrations=new[]{new RawRegistration{Page=1,Usage=2,Flags=0x2100,Target=hwnd},new RawRegistration{Page=1,Usage=6,Flags=0x2100,Target=hwnd},new RawRegistration{Page=1,Usage=4,Flags=0x2100,Target=hwnd},new RawRegistration{Page=1,Usage=5,Flags=0x2100,Target=hwnd},new RawRegistration{Page=1,Usage=8,Flags=0x2100,Target=hwnd}};if(!Native.RegisterRawInputDevices(registrations,(uint)registrations.Length,(uint)Marshal.SizeOf(typeof(RawRegistration)))){Log("Raw Input : "+new Win32Exception().Message);return;}rawNames.Clear();rawBuffer=Marshal.AllocHGlobal(65536);testing=true;inputClock.Restart();inputTimer.Start();Find<Button>("InputButton").IsEnabled=false;Set("InputState","Observation · "+(selected==null?"all devices":selected.Name));Log("10-second Raw Input observation started: "+(inputTarget.Length==0?"all devices":inputTarget));}
  void StopInput(){if(!testing)return;testing=false;if(rawBuffer!=IntPtr.Zero){Marshal.FreeHGlobal(rawBuffer);rawBuffer=IntPtr.Zero;}rawNames.Clear();inputTimer.Stop();inputClock.Stop();var regs=new ushort[]{4,5,8}.Select(x=>new RawRegistration{Page=1,Usage=x,Flags=1,Target=IntPtr.Zero}).ToArray();if(!Native.RegisterRawInputDevices(regs,(uint)regs.Length,(uint)Marshal.SizeOf(typeof(RawRegistration))))Log("Raw Input stop: "+new Win32Exception().Message);Find<Button>("InputButton").IsEnabled=!busy;Set("InputState","Observation completed · "+inputClock.Elapsed.TotalSeconds.ToString("F1")+" s. An idle device does not indicate a fault.");Log("Observation completed · "+inputCount+" event(s).");}
  void InputTick(){Set("InputCount",inputCount+" event(s)");Set("InputDetail",lastInput);if(inputClock.ElapsedMilliseconds>=10000)StopInput();}
  IntPtr WndProc(IntPtr handle,int message,IntPtr wParam,IntPtr lParam,ref bool handled){if(message==0x219||message==0xFE){rawNames.Clear();debounce.Stop();debounce.Start();}if(message==0xFF&&testing)ReadInput(lParam);return IntPtr.Zero;}
  void ReadInput(IntPtr raw){uint bytes=65536;uint header=IntPtr.Size==8?24u:16u;IntPtr buffer=rawBuffer;if(buffer==IntPtr.Zero)return;uint got=Native.GetRawInputData(raw,0x10000003,buffer,ref bytes,header);if(got<header||got>65536)return;int type=Marshal.ReadInt32(buffer),offset=(int)header;IntPtr device=Marshal.ReadIntPtr(buffer,8);string instance;if(!rawNames.TryGetValue(device,out instance)){uint nameSize=2048;var name=new StringBuilder(2048);Native.GetRawInputDeviceInfo(device,0x20000007,name,ref nameSize);instance=RawInstance(name.ToString());rawNames[device]=instance;}if(inputTarget.Length>0&&!instance.Equals(inputTarget,StringComparison.OrdinalIgnoreCase))return;long tick=Stopwatch.GetTimestamp();if(lastInputTick!=0)maxGap=Math.Max(maxGap,(tick-lastInputTick)*1000.0/Stopwatch.Frequency);lastInputTick=tick;inputCount++;string text=type==0&&got>=header+24?"Mouse  dx="+Marshal.ReadInt32(buffer,offset+12)+" dy="+Marshal.ReadInt32(buffer,offset+16)+" boutons=0x"+((ushort)Marshal.ReadInt16(buffer,offset+4)).ToString("X4"):type==1&&got>=header+16?"Keyboard  scan=0x"+((ushort)Marshal.ReadInt16(buffer,offset)).ToString("X2")+" flags="+((ushort)Marshal.ReadInt16(buffer,offset+2)):"HID  "+(got-header)+" octets";lastInput=text+"\n"+instance;}
  internal static string RawInstance(string name){if(name.StartsWith(@"\\?\"))name=name.Substring(4);int tail=name.LastIndexOf("#{",StringComparison.Ordinal);if(tail>=0)name=name.Substring(0,tail);return name.Replace('#','\\');}
 }
